"""Local-only calibration; requires ffmpeg + numpy. Never modifies source audio."""
import concurrent.futures, json, math, pathlib, re, subprocess
import numpy as np
ROOT = pathlib.Path(__file__).resolve().parents[1]
node = r'''const fs=require('fs'),vm=require('vm'),window={};for(const f of ['audio/catalog.js','audio/extra-catalog.js','audio/play-catalog.js','audio/files.js','audio/play-files.js','audio/sfx.js'])vm.runInNewContext(fs.readFileSync(f,'utf8'),{window});console.log(JSON.stringify(window));'''
w=json.loads(subprocess.check_output(['node','-e',node],cwd=ROOT))
ids=['common-0','common-1','closing','opening','up','down','arrival-1','play-drag-help','play-potty-drag-0']
def db(x): return round(20*math.log10(max(float(x),1e-12)),3)
def measure(item):
    name,src=item
    x=np.frombuffer(subprocess.check_output(['ffmpeg','-v','error','-i',str(ROOT/src),'-f','f32le','-ac','1','-ar','48000','-']),dtype='<f4')
    blocks=x[:len(x)//960*960].reshape(-1,960)
    r=np.sqrt(np.mean(blocks**2,axis=1)); active=r[r>max(r)*.1]
    log=subprocess.run(['ffmpeg','-hide_banner','-nostats','-i',str(ROOT/src),'-af','ebur128=peak=true','-f','null','-'],capture_output=True,text=True,check=True).stderr
    lufs=re.findall(r'I:\s*(-?[\d.]+) LUFS',log)[-1];peak=re.findall(r'Peak:\s*(-?[\d.]+) dBFS',log)[-1]
    return name,dict(src=src,duration=round(len(x)/48000,3),rmsDb=db(np.sqrt(np.mean(x*x))),activeRmsDb=db(np.sqrt(np.mean(active**2))),peakDb=db(max(abs(x))),truePeakDb=float(peak),lufs=float(lufs))
items=[(k,w['SEOWOO_AUDIO_FILES'][k]) for k in ids]+[(k,v['src']) for k,v in w['SEOWOO_SFX'].items()]
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool: measured=dict(pool.map(measure,items))
reference=round(float(np.median([measured[k]['activeRmsDb'] for k in ids])),3)
profile={}
for k,s in w['SEOWOO_SFX'].items():
    row=measured[k];target=reference-({'motorStart':15,'motorStop':8,'doorOpen':8,'doorClose':8,'flush':8}.get(k,5))
    gainDb=min(target-row['activeRmsDb'],-10-row['truePeakDb'],6)
    gain=round(10**(gainDb/20),5);profile[s['src']]=gain
    row.update(targetActiveRmsDb=round(target,3),gain=gain,beforeActiveRmsDb=round(row['activeRmsDb']+db(s.get('gain',1)*.9),3),afterActiveRmsDb=round(row['activeRmsDb']+db(gain*.9),3),afterTruePeakDb=round(row['truePeakDb']+db(gain*.9),3))
report=dict(referenceActiveRmsDb=reference,referenceIds=ids,windowMs=20,activeGateDbBelowMax=-20,realListeningPerformed=False,notes='LUFS reported for context; short events calibrated by active 20ms RMS + true peak, duration and role. Runtime nonvoice ceiling and ducking apply in addition. No source media modified.',measurements=measured)
(ROOT/'docs/audio-calibration.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
(ROOT/'js/audio-profile.js').write_text('/* Generated by scripts/analyze-audio.py; linear gains, source media unchanged. */\nwindow.SEOWOO_AUDIO_PROFILE = '+json.dumps(dict(referenceActiveRmsDb=reference,files=profile),indent=2)+';\n')
print(json.dumps(dict(reference=reference,gains=profile),indent=2))
